'use strict';

// MODULES //

var stride2offset = require( '@stdlib/strided/base/stride2offset' );
var ndarray = require( './ndarray.js' );


// MAIN //

/**
* Computes the sum of single-precision floating-point strided array elements, ignoring `NaN` values, using an improved Kahan–Babuška algorithm, and returning the number of non-`NaN` elements.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Float32Array} x - input array
* @param {integer} strideX - stride length for `x`
* @param {Float32Array} sum - output array for storing the sum
* @param {Int64Array} count - output array for storing the number of non-NaN elements
* @returns {Float32Array} `sum`
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var Int64Array = require( '@stdlib/array/int64' );
*
* var x = new Float32Array( [ 1.0, -2.0, NaN, 2.0 ] );
* var sum = new Float32Array( 1 );
* var count = new Int64Array( 1 );
*
* var v = snannsumkbn( x.length, x, 1, sum, count );
* // returns <Float32Array>[ 1.0 ]
*
* var n = count.get( 0 );
* // returns <Int64>[ 3n ]
*/
function snannsumkbn( N, x, strideX, sum, count ) {
	return ndarray( N, x, strideX, stride2offset( N, strideX ), sum, 0, count, 0 );
}


// EXPORTS //

module.exports = snannsumkbn;
